package org.marketreview.nativeapp;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
/** Explicit local security research, immutable originals and separate source clocks. */
final class StockResearchModel {
 static void need(boolean b,String why){if(!b)throw new IllegalArgumentException(why);}
 static String canonical(Object v)throws Exception{if(v instanceof JSONObject){JSONObject o=(JSONObject)v;List<String> keys=new ArrayList<>();o.keys().forEachRemaining(keys::add);Collections.sort(keys);List<String> parts=new ArrayList<>();for(String k:keys)parts.add(JSONObject.quote(k)+":"+canonical(o.get(k)));return "{"+String.join(",",parts)+"}";}if(v instanceof JSONArray){JSONArray a=(JSONArray)v;List<String> parts=new ArrayList<>();for(int i=0;i<a.length();i++)parts.add(canonical(a.get(i)));return "["+String.join(",",parts)+"]";}if(v==null||v==JSONObject.NULL)return "null";if(v instanceof String)return JSONObject.quote((String)v);if(v instanceof Number)return JSONObject.numberToString((Number)v);return v.toString();}
 static void identity(String id){need(id.matches("^(SH|SZ|BJ):(stock|etf|index):[0-9]{6}$"),"必须明确完整市场、证券类型和六位代码");String[] p=id.split(":");String m=p[0],t=p[1],c=p[2];boolean ok=t.equals("stock")?(m.equals("SH")?c.startsWith("6")||c.startsWith("9"):m.equals("SZ")?c.startsWith("0")||c.startsWith("3"):c.startsWith("4")||c.startsWith("8")||c.startsWith("92")):t.equals("etf")?(m.equals("SH")?c.startsWith("5"):m.equals("SZ")&&(c.startsWith("15")||c.startsWith("16"))):(m.equals("SH")?c.startsWith("000"):m.equals("SZ")&&c.startsWith("399"));need(ok,"市场/证券类型与代码不一致，未猜测身份");}
 static JSONObject bundle(String id,JSONObject input)throws Exception{identity(id);need(id.equals(input.optString("id")),"宿主资料与所选完整证券身份不一致");need(input.toString().getBytes(StandardCharsets.UTF_8).length<=16*1024*1024,"证券资料超过16MB，请分批研究");if(input.has("companyProfile")){JSONObject p=input.getJSONObject("companyProfile");need("native-stock-company-profile/v1".equals(p.optString("schema"))&&id.equals(p.optString("id")),"公司主营资料与研究完整证券身份不一致");}if(input.has("documents")){JSONArray docs=input.getJSONArray("documents");Set<String> ids=new HashSet<>();for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);need(!d.optString("id").isEmpty()&&d.opt("text") instanceof String&&d.getString("text").length()<=600000,"证据原记录缺失或过长");need(ids.add(d.getString("id")),"证据身份重复");}}return new JSONObject(input.toString());}
 static JSONObject snapshot(String key,String id,JSONObject input,String note,String at)throws Exception{need(!key.isEmpty()&&key.length()<=100,"快照ID无效");need(note.length()<=100000,"笔记过长");Instant.parse(at);return new JSONObject().put("id",key).put("instrumentId",id).put("capturedAt",at).put("note",note).put("bundle",bundle(id,input));}
 static JSONObject validate(String kind,JSONObject r)throws Exception{if(kind.equals("notes")){identity(r.optString("id"));need(r.opt("text") instanceof String&&r.getString("text").length()<=100000&&r.opt("revision") instanceof Number&&r.optDouble("revision")>=1&&r.optDouble("revision")==r.optInt("revision"),"笔记字段/版本无效");return r;}need(kind.equals("snapshots"),"未知研究记录类型");JSONObject valid=snapshot(r.getString("id"),r.getString("instrumentId"),r.getJSONObject("bundle"),r.getString("note"),r.getString("capturedAt"));need(canonical(valid).equals(canonical(r)),"快照字段与原记录不一致");return valid;}
 static JSONObject decode(String text)throws Exception{need(text.getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"导入超过32MB");JSONTokener parser=new JSONTokener(text);Object value=parser.nextValue();need(value instanceof JSONObject&&parser.nextClean()==0,"导入JSON无效");JSONObject o=(JSONObject)value;need("stock-research/v1".equals(o.optString("schema")),"不支持的个股研究备份");for(String k:new String[]{"notes","snapshots"}){JSONArray rows=o.getJSONArray(k);need(rows.length()<=10000,"备份超过10000条");Set<String> seen=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=validate(k,rows.getJSONObject(i));need(seen.add(r.getString("id")),"备份ID重复");}}return new JSONObject(o.toString());}
 static JSONObject preview(JSONObject incoming,JSONObject current)throws Exception{JSONObject inserts=new JSONObject();JSONArray conflicts=new JSONArray();int duplicates=0;for(String k:new String[]{"notes","snapshots"}){Map<String,JSONObject> existing=new HashMap<>();JSONArray previous=current.getJSONArray(k),out=new JSONArray();for(int i=0;i<previous.length();i++)existing.put(previous.getJSONObject(i).getString("id"),previous.getJSONObject(i));JSONArray rows=incoming.getJSONArray(k);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i),old=existing.get(r.getString("id"));if(old==null)out.put(r);else if(canonical(old).equals(canonical(r)))duplicates++;else conflicts.put(k+":"+r.getString("id"));}inserts.put(k,out);}return new JSONObject().put("inserts",inserts).put("duplicates",duplicates).put("conflicts",conflicts);}
 static String display(JSONObject o,String key){Object value=o.opt(key);return value==null||value==JSONObject.NULL?"未提供":value instanceof Boolean?((Boolean)value?"是":"否"):String.valueOf(value);}
 static String overview(JSONObject b)throws Exception{StringBuilder out=new StringBuilder("完整身份："+b.optString("id")+" · "+b.optString("name")+"\n行情：\n");JSONObject q=b.optJSONObject("quote");if(q!=null)out.append("报价："+display(q,"price")+" · 涨跌幅（%）："+display(q,"changePercent")+"\n行情时点："+display(q,"tradeDate")+" "+display(q,"tradeTime")+"\n行情来源："+display(q,"source")+" · 缓存："+display(q,"cached")+"\n本机检查时点："+display(q,"checkedAt")+"\n");out.append(q==null?"不可得；未补0":q.toString(2));for(String k:new String[]{"day","minute","capitalDay","capitalMinute","capitalSnapshot"}){JSONArray rows=b.optJSONArray(k);JSONObject meta=b.optJSONObject(k+"Meta");out.append("\n"+k+"：本机覆盖 "+(rows==null?0:rows.length())+" 点\n"+(meta==null?"来源时点与覆盖元数据未提供":meta.toString(2)));}out.append("\n主营 / 行业 / 标签（仅已有资料）：\n");for(String k:new String[]{"industry","csrcIndustry","businessSummary","mainBusinessItems","tags","profile","news","watchlist","accountPositions","source","sourceUrl","fetchedAt","cached"})out.append(k+"："+(b.has(k)?String.valueOf(b.get(k)):"未提供")+"\n");return out.append("\n源时间分别显示；保存时间不是行情或资料时点。完整冻结原文\n"+b.toString(2)).toString();}
}
